import json

def short(o, n=1500):
    try:
        s = json.dumps(o, default=str)
    except Exception:
        s = str(o)
    return s[:n]

def find_handles(o, acc):
    if isinstance(o, dict):
        for k, v in o.items():
            if k in ("evidence_handle", "handle") and isinstance(v, str):
                acc.append(v)
            elif k in ("evidence_handles", "handles") and isinstance(v, list):
                for h in v:
                    if isinstance(h, str):
                        acc.append(h)
            else:
                find_handles(v, acc)
    elif isinstance(o, list):
        for v in o:
            find_handles(v, acc)
    return acc

handles = []
r = primitives.call(name='observe_robotwin2_visual', camera_name='head_camera', prompt='locate blocks for pick and place')
print("visual ok", r.ok)
if r.ok:
    find_handles(r.output, handles)
    if isinstance(r.output, dict):
        print("visual keys", list(r.output.keys())[:20])
else:
    print("visual err", short(r.output, 500))

measures = {}
for lbl in ["block1", "block2", "block3"]:
    m = primitives.call(name='measure_robotwin2_actor_visual', actor_label=lbl, camera_name='head_camera', prompt='measure block for grasp')
    print(lbl, "measure ok", m.ok)
    if m.ok:
        find_handles(m.output, handles)
        measures[lbl] = m.output
        if isinstance(m.output, dict):
            print(lbl, "keys", list(m.output.keys())[:20])
            for k in ("centroid_world", "center_world", "position_world", "pose_world", "evidence_handle"):
                if k in m.output:
                    print(lbl, k, short(m.output[k], 200))
    else:
        print(lbl, "measure err", short(m.output, 600))

handles = list(dict.fromkeys(handles))
print("handles", handles)
if not handles and r.ok:
    print("visual out", short(r.output, 2500))

